import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"抓包与流量分析","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/抓包与流量分析.md","filePath":"必学工具/抓包与流量分析.md","lastUpdated":1792430298000}'),o={name:"必学工具/抓包与流量分析.md"};function i(d,t,h,s,n,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="抓包与流量分析" tabindex="-1">抓包与流量分析 <a class="header-anchor" href="#抓包与流量分析" aria-label="Permalink to &quot;抓包与流量分析&quot;">​</a></h1><blockquote><p>网络安全的「显微镜」。看懂数据包，才能理解攻击如何发生、协议如何被利用，也是数字取证与应急响应的基本功。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>校内「网络安全原理」「网络攻防技术」课程的核心实验就是抓包分析；</li><li>排查问题（连接异常、恶意流量、漏洞验证）离不开流量视角；</li><li>取证方向（数字取证、网络舆情）的日常就是分析流量与日志。</li></ul><h2 id="工具选择" tabindex="-1">工具选择 <a class="header-anchor" href="#工具选择" aria-label="Permalink to &quot;工具选择&quot;">​</a></h2><ul><li><strong>Wireshark</strong>：图形化抓包分析，功能最全，<a href="https://www.wireshark.org/" target="_blank" rel="noreferrer">官网下载</a>；</li><li><strong>tcpdump</strong>：命令行抓包，服务器上最常用（<code>sudo tcpdump -i eth0 -w cap.pcap</code>）；</li><li><strong>TShark</strong>：Wireshark 的命令行版本，适合脚本化分析。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li>会抓包：选定网卡 → 开始抓取 → 停止保存（<code>.pcap</code> 文件）；</li><li>会看包：理解<strong>分层模型</strong>（以太网 / IP / TCP / HTTP 等），看懂三次握手、HTTP 请求响应；</li><li>会用过滤器：显示过滤器（<code>http</code>、<code>tcp.port == 443</code>、<code>ip.src == x.x.x.x</code>）是效率关键；</li><li>会追踪流：右键「Follow TCP Stream」还原一次完整会话。</li></ol><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://www.wireshark.org/docs/" target="_blank" rel="noreferrer">Wireshark 官方文档</a></td><td>文档</td><td>含捕获/过滤手册</td></tr><tr><td>《Wireshark 数据包分析实战》</td><td>书</td><td>经典实战入门（注意选择较新版本）</td></tr><tr><td>Wireshark 官网捕获示例（Sample Captures）</td><td>练习</td><td>官方提供的真实流量包供练习</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>配合 <a href="./../专业基础/计算机网络.html">计算机网络</a> 一起学，抓包是对网络理论最好的验证；</li><li>用 Wireshark 复现课程中学过的每个协议（DHCP、DNS、HTTP、HTTPS…）；</li><li>CTF 中 Misc 方向经常考流量分析，练好后一举两得。</li></ul>',12)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
